import {createRouteNavigation} from './route-navigation.js?v=22';
import * as THREE from 'three';
import {createRouter,simulate,options,cleanJourneys,upgradeSeaPace} from './travel-core.js?v=24';
const KEY='silvengard-journeys-v1',esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=n=>Number(n).toLocaleString('pt-BR',{maximumFractionDigits:1});
function confirmJourney(message){return new Promise(resolve=>{const d=document.createElement('dialog');d.className='journeyConfirm';d.innerHTML=`<form method="dialog"><h2>Confirmar alteração</h2><p>${esc(message)}</p><div class="journeyRow"><button value="cancel">Cancelar</button><button value="confirm">Confirmar</button></div></form>`;d.addEventListener('close',()=>{const yes=d.returnValue==='confirm';d.remove();resolve(yes);},{once:true});document.body.append(d);d.showModal();});}
export function createJourneys({D,world,point,focus,toast,changed,title,visible}){
 let data=D.defaultJourneys?cleanJourneys(D.defaultJourneys):{version:1,active:null,parties:[],defaultScale:D.settings.distanceScale};try{const saved=localStorage.getItem(KEY);if(saved)data=cleanJourneys(JSON.parse(saved));}catch{toast('Não foi possível restaurar as jornadas. Importe sua cópia de segurança.');}
 if(data.scaleVersion!==D.settings.journeyScaleVersion){const previous=data.defaultScale;data.defaultScale=D.settings.distanceScale;for(const p of data.parties)if(p.settings.scale===previous)p.settings.scale=D.settings.distanceScale;data.scaleVersion=D.settings.journeyScaleVersion;try{localStorage.setItem(KEY,JSON.stringify(data));}catch{}}
 if(data.seaPaceVersion!==17){upgradeSeaPace(data);try{localStorage.setItem(KEY,JSON.stringify(data));}catch{}}
 const router=createRouter(D),overlay=new THREE.Group();overlay.name='Jornadas';world.add(overlay);
 const panel=document.createElement('aside');panel.id='journeys';panel.hidden=true;panel.setAttribute('aria-label','Jornadas e grupos');document.body.append(panel);
 let picking=null,lastRoute=null,lastSimulation=null,routeError='',collapsed=false,routeDraft='';
 const tour=createRouteNavigation({D,focus,title});let browseRouteId=null;
 const active=()=>data.parties.find(p=>p.id===data.active),$=s=>panel.querySelector(s);
 function persist(){try{localStorage.setItem(KEY,JSON.stringify(data));}catch{toast('Armazenamento cheio ou indisponível. Exporte a edição para guardar as jornadas.');}}
 function dispose(){for(const child of [...overlay.children]){overlay.remove(child);child.traverse(o=>{o.geometry?.dispose();if(o.material)for(const m of Array.isArray(o.material)?o.material:[o.material])m.dispose();});}}
 function line(points,color,opacity=.95){if(points.length<2)return;const vertices=[];for(let i=1;i<points.length;i++){const a=points[i-1],b=points[i],steps=Math.max(1,Math.ceil(Math.hypot(a[0]-b[0],a[1]-b[1])/2));for(let j=0;j<steps;j++){const p=j/steps,q=(j+1)/steps;vertices.push(point(a[0]+(b[0]-a[0])*p,a[1]+(b[1]-a[1])*p,2.8),point(a[0]+(b[0]-a[0])*q,a[1]+(b[1]-a[1])*q,2.8));}}const ribbon=[];for(let i=0;i<vertices.length;i+=2){const a=vertices[i],b=vertices[i+1],side=new THREE.Vector3(b.z-a.z,0,a.x-b.x).normalize().multiplyScalar(.52),v=[a.clone().add(side),a.clone().sub(side),b.clone().add(side),b.clone().sub(side)];for(const j of [0,1,2,2,1,3])ribbon.push(v[j].x,v[j].y,v[j].z);}const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.Float32BufferAttribute(ribbon,3));const mesh=new THREE.Mesh(geo,new THREE.MeshBasicMaterial({color,transparent:true,opacity,depthTest:false,depthWrite:false,side:THREE.DoubleSide}));mesh.renderOrder=12;overlay.add(mesh);}
 function marker(p,color,r=3){const m=new THREE.Mesh(new THREE.SphereGeometry(r,12,8),new THREE.MeshBasicMaterial({color,depthTest:false}));m.position.copy(point(...p,6));m.renderOrder=13;overlay.add(m);}
 function calculate(){lastRoute=null;lastSimulation=null;routeError='';const p=active();if(!p){dispose();changed();return;}try{lastRoute=router.route(p.waypoints,p.settings.scale,p.settings.terrain);lastSimulation=simulate(lastRoute.segments,p.settings);}catch(e){routeError=e.message;}dispose();for(const party of data.parties){if(party===p)for(const h of p.history)line(h.points,'#91bca4',.55);if(party.location)marker(party.location.xy,party===p?'#ffe0a0':'#84c5dc',party===p?4:2.5);}if(lastRoute)line(lastRoute.points,'#ffd080');for(const wp of p.waypoints)marker(wp.xy,'#ffcd77',1.8);changed();}
 function result(){const s=lastSimulation;if(routeError)return `<p class="journeyError" role="alert">${esc(routeError)}</p>`;if(!s||!s.distance)return '<p class="muted">Marque a posição do grupo e adicione destinos para simular por terra e mar.</p>';const checks=s.days.flatMap(d=>d.saves.map(x=>`Dia ${d.day}, hora ${x.hour}: CD ${x.dc}`));return `<div class="journeyStats"><span><b>${fmt(s.distance)} km</b>Distância total</span><span><b>${fmt(s.moving)} h</b>Em movimento</span><span><b>${s.days.length} dia${s.days.length===1?'':'s'}</b>De viagem</span><span><b>${fmt(s.elapsed)} h</b>Até a chegada*</span></div><p class="source">${esc(s.effect)} · ${fmt(s.speed)} km/h em terreno normal${active().settings.gallop&&active().settings.mode==='mount'?' · Galope: 12 km/h, até 1 h por dia':''}.<br>*Inclui noites entre dias de viagem e ${fmt(s.rest)} h de descanso após galope. Terreno difícil fora das estradas reduz a velocidade à metade. ${s.seaDistance?`<br>⚓ ${fmt(s.seaDistance)} km por mar · ${fmt(s.seaMoving)} h a ${fmt(s.shipSpeed)} km/h. Passageiros não fazem marcha forçada a bordo.`:''}</p>${s.warnings.map(w=>`<p class="journeyError">${esc(w)}</p>`).join('')}${checks.length?`<details><summary>Marcha forçada · ${checks.length} testes de Constituição</summary><p class="source">Cada personagem faz estes testes. Cada falha causa 1 nível de Exaustão.</p><ul>${checks.slice(0,150).map(x=>`<li>${x}</li>`).join('')}</ul>${checks.length>150?'<p>Lista limitada aos 150 primeiros testes.</p>':''}</details>`:'<p class="source">Sem testes de marcha forçada neste percurso.</p>'}`;}
 function setting(key,label,type='number',extra=''){const v=active().settings[key];return `<label>${label}<input data-setting="${key}" type="${type}" ${type==='checkbox'?(v?'checked':''):`value="${v}"`} ${extra}></label>`;}
 function select(key,label,items){return `<label>${label}<select data-setting="${key}">${items.map(([v,t])=>`<option value="${v}" ${active().settings[key]===v?'selected':''}>${t}</option>`).join('')}</select></label>`;}
 function render(){const scrollTop=$('#journeyBody')?.scrollTop||0;const p=active();panel.innerHTML=`<div class="journeyHeading"><div><div class="eyebrow">CAMINHOS E MEMÓRIAS</div><h2>Jornadas</h2></div><button id="journeyFold" title="Recolher ou expandir">${collapsed?'▾':'▴'}</button><button id="journeyClose" title="Fechar jornadas">×</button></div><div class="journeyPick" role="status">${picking==='location'?'Clique em terra, em um porto ou numa rota marítima para posicionar o grupo.':picking==='route'?'Clique no mapa para adicionar paradas em terra ou nas rotas marítimas. Arraste para mover a câmera.':'Terra e mar · grupos e histórico salvos neste navegador.'}${picking?'<button id="journeyDone">Concluir marcação</button>':''}</div><div id="journeyBody" ${collapsed?'hidden':''}>${tour.html(D.routes.find(r=>r.id===browseRouteId)|| (lastRoute?.points?.length?{id:'journey-'+data.active,points:lastRoute.points,kind:'road'}:null))}<div class="journeyScale"><label>Escala de viagem · km por unidade do mapa<input id="journeyMapScale" aria-label="Quilômetros por unidade do mapa" type="number" min="0.001" max="10000" step="0.1" value="${p?.settings.scale??data.defaultScale??D.settings.distanceScale}"></label><div class="journeyRow"><button data-scale="1.5">1,5 km</button><button data-scale="1">1 km</button><button data-scale="5">5 km</button><button data-scale="10">10 km</button></div><p class="source">Padrão do atlas: 1,5 km por unidade. O valor recalcula distância e horas em movimento. Aplica-se ao plano atual e vira o padrão de novos grupos; o histórico permanece como foi registrado.</p></div><div class="journeyRow"><label class="grow">Grupo<select id="partySelect" aria-label="Grupo">${data.parties.map(a=>`<option value="${esc(a.id)}" ${a===p?'selected':''}>${esc(a.name)}</option>`).join('')||'<option>Nenhum grupo</option>'}</select></label><button id="newParty">+ Criar</button></div><form id="partyCreate" hidden><label>Nome do grupo<input id="newPartyName" maxlength="100" required placeholder="Companhia do Amanhecer"></label><label>Jogadores (opcional)<textarea id="newPartyPlayers" maxlength="1000" placeholder="Um nome por linha"></textarea></label><button>Criar grupo</button></form>${p?`<details><summary>Editar grupo e jogadores</summary><label>Nome<input id="partyName" maxlength="100" value="${esc(p.name)}"></label><label>Jogadores (opcional)<textarea id="partyPlayers" maxlength="1000">${esc(p.players)}</textarea></label><div class="journeyRow"><button id="partySave">Salvar grupo</button><button id="partyDelete">Excluir grupo…</button></div></details><div class="journeyLocation"><small>POSIÇÃO ATUAL</small><strong>${esc(p.location?.label||'Ainda não definida')}</strong><div class="journeyRow"><button id="locateParty">Marcar posição</button>${p.location?'<button id="focusParty">Ver no mapa ↗</button>':''}</div></div><label>Cidade de origem ou destino<select id="journeyCity"><option value="">Escolha uma cidade…</option>${D.cities.filter(visible).sort((a,b)=>title(a).localeCompare(title(b),'pt')).map(b=>`<option value="${b.i}">${esc(title(b))} · ${esc(D.states.find(s=>s.i===b.state)?.name||'Terras livres')}</option>`).join('')}</select></label><div class="journeyRow"><button id="cityOrigin">Usar como posição</button><button id="cityDestination">Adicionar destino</button></div><details><summary>Seguir estrada ou rota marítima</summary><select id="journeyRegisteredRoute"><option value="">Escolha um traçado…</option>${D.routes.filter(r=>r.enabled!==false&&r.majorRoute!==false).map(r=>`<option value="${esc(r.id)}">${r.kind==='sea'?'⚓ ':'↝ '}${esc(r.name)}</option>`).join('')}</select><button id="appendRegisteredRoute">Adicionar percurso</button></details><h3>Traçar percurso</h3><ol class="waypoints">${p.waypoints.map((w,i)=>`<li><button data-waypoint="${i}" title="Ver ponto">${esc(w.label||'Ponto no mapa')}</button>${i?`<button data-remove-waypoint="${i}" title="Remover parada">×</button>`:'<small> início</small>'}</li>`).join('')}</ol><div class="journeyRow"><button id="drawRoute">${picking==='route'?'Concluir marcação':'Marcar no mapa'}</button><button id="undoRoute">Desfazer</button><button id="clearRoute">Limpar</button></div><details open><summary>Parâmetros da viagem</summary><div class="journeyGrid">${select('pace','Ritmo',[['normal','Normal · 4,5 km/h'],['fast','Rápido · 6 km/h'],['slow','Lento · 3 km/h']])}${select('mode','Transporte em terra',[['foot','A pé'],['mount','Montaria'],['vehicle','Carroça / veículo']])}${setting('hours','Horas em movimento por dia','number','min="1" max="24" step="0.5"')}<label>Ritmo marítimo<select id="journeySeaPace">${[[6,'Lento · 6 km/h'],[11,'Médio · 11 km/h'],[20,'Rápido · 20 km/h'],['custom','Personalizado']].map(([speed,label])=>`<option value="${speed}" ${(speed==='custom'?![6,11,20].includes(p.settings.shipSpeed):speed===p.settings.shipSpeed)?'selected':''}>${label}</option>`).join('')}</select></label>${setting('shipSpeed','Embarcação · km/h','number','min="0.1" max="100" step="0.1"')}${select('terrain','Terreno',[['auto','Detectar pelo mapa'],['easy','Normal (inclui estrada transitável)'],['difficult','Todo o percurso é difícil']])}</div><p class="source">Escala padrão: ${D.settings.distanceScale} km por unidade. Estradas e rotas marítimas cadastradas são terreno normal. Montanhas íngremes, pântanos e florestas densas são difíceis. O caminho é calculado pelas células e pode mudar com atualizações do mapa. A posição é uma aproximação cartográfica.</p>${p.settings.mode==='mount'?`<div class="journeyGrid">${setting('gallop','Usar galope · até 1 h/dia','checkbox')}${setting('rest','Descanso após galope · horas','number','min="0" max="24" step="0.5"')}${setting('fresh','Montarias frescas para revezamento','checkbox')}</div><p class="source">Um galope por dia neste modelo. O descanso informado é obrigatório após completar 1 h, caso a viagem continue. Trocas não dispensam a marcha forçada dos personagens.</p>`:''}${p.settings.mode==='vehicle'?`<div class="journeyGrid">${setting('load','Peso total puxado · kg','number','min="0" step="1"')}${setting('capacity','Capacidade normal dos animais · kg','number','min="0" step="1"')}</div><p class="source">Some as capacidades normais dos animais de tração. Limite puxado = 5 × esse valor. Inclua veículo e carga no peso; o ritmo do veículo é normal.</p>`:''}</details><div id="journeyResult" aria-live="polite">${result()}</div><label>Nome do trecho<input id="routeName" maxlength="100" value="${esc(routeDraft)}" placeholder="Pela estrada de Baranor"></label><div class="journeyRow"><button id="savePlan">Salvar plano</button><button id="recordJourney">Registrar como percorrido</button></div><p class="source">Simular e salvar plano não movem o grupo. Registrar atualiza sua posição e guarda o caminho realmente percorrido. Testes e Exaustão são resolvidos na mesa.</p>${p.plans.length?`<details><summary>Planos salvos · ${p.plans.length}</summary>${p.plans.map((r,i)=>`<div class="journeyRow"><button data-plan="${i}">${esc(r.name)}</button><button data-delete-plan="${i}" title="Excluir plano">×</button></div>`).join('')}</details>`:''}<details ${p.history.length?'open':''}><summary>Histórico · ${p.history.length} trecho${p.history.length===1?'':'s'}</summary>${p.history.map((h,i)=>`<article class="journeyHistory"><b>${esc(h.name)}</b><p>${esc(h.from)} → ${esc(h.to)}<br>${fmt(h.distance)} km · ${fmt(h.moving)} h em movimento<br>${esc(new Date(h.date).toLocaleString('pt-BR'))}</p><button data-history="${i}">Ver caminho ↗</button></article>`).join('')||'<p class="muted">Os trechos percorridos aparecerão aqui.</p>'}</details>`:'<p class="muted">Crie um grupo para marcar a origem, traçar uma rota e guardar sua jornada.</p>'}<p class="source">Guarde uma cópia com <b>Exportar edição</b>. A exportação inclui todos os grupos, planos e históricos.</p></div>`;
  tour.bind(panel);$('#journeyClose').onclick=()=>{panel.hidden=true;picking=null;};$('#journeyFold').onclick=()=>{collapsed=!collapsed;render();};if($('#journeyDone'))$('#journeyDone').onclick=()=>{picking=null;collapsed=false;render();};$('#newParty').onclick=()=>{$('#partyCreate').hidden=false;collapsed=false;$('#newPartyName').focus();};$('#partyCreate').onsubmit=e=>{e.preventDefault();const name=$('#newPartyName').value.trim();if(!name)return;const party={id:crypto.randomUUID(),name,players:$('#newPartyPlayers').value.trim(),location:null,waypoints:[],settings:options({scale:data.defaultScale??D.settings.distanceScale,rest:8}),history:[],plans:[]};if(data.parties.length>=50)return toast('Limite de 50 grupos. Exporte e remova grupos antigos.');data.parties.push(party);data.active=party.id;picking=null;persist();calculate();render();};const applyScale=value=>{data.defaultScale=options({scale:value}).scale;if(p)p.settings.scale=data.defaultScale;persist();calculate();if($('#journeyResult'))$('#journeyResult').innerHTML=result();};$('#journeyMapScale').oninput=e=>applyScale(e.target.value);$('#journeyMapScale').onblur=e=>e.target.value=p?.settings.scale??data.defaultScale;panel.querySelectorAll('[data-scale]').forEach(b=>b.onclick=()=>{applyScale(+b.dataset.scale);$('#journeyMapScale').value=data.defaultScale;});$('#partySelect').onchange=e=>{data.active=e.target.value;picking=null;persist();calculate();render();};if(!p)return;
  $('#partySave').onclick=()=>{p.name=$('#partyName').value.trim()||p.name;p.players=$('#partyPlayers').value;persist();render();toast('Grupo salvo');};$('#partyDelete').onclick=async()=>{if(!await confirmJourney(`Excluir ${p.name} e todo o seu histórico? Exporte antes para guardar uma cópia.`))return;data.parties=data.parties.filter(a=>a!==p);data.active=data.parties[0]?.id||null;picking=null;persist();calculate();render();};$('#locateParty').onclick=()=>startPick('location');if($('#focusParty'))$('#focusParty').onclick=()=>focus(...p.location.xy,180);
  const chosenCity=()=>D.cities.find(b=>b.i===Number($('#journeyCity').value));$('#cityOrigin').onclick=()=>{const b=chosenCity();if(b){picking='location';pick([b.x,b.y],title(b));}else toast('Escolha uma cidade.');};$('#cityDestination').onclick=()=>{const b=chosenCity();if(b){picking='route';pick([b.x,b.y],title(b));}else toast('Escolha uma cidade.');};$('#appendRegisteredRoute').onclick=()=>{const r=D.routes.find(r=>r.id===$('#journeyRegisteredRoute').value);if(r)planRoute(r);else toast('Escolha um traçado cadastrado.');};$('#drawRoute').onclick=()=>{if(picking==='route'){picking=null;collapsed=false;render();}else startPick('route');};$('#undoRoute').onclick=()=>{if(p.waypoints.length>1)p.waypoints.pop();persist();calculate();render();};$('#clearRoute').onclick=()=>{p.waypoints=p.location?[structuredClone(p.location)]:[];persist();calculate();render();};
  panel.querySelectorAll('[data-waypoint]').forEach(b=>b.onclick=()=>focus(...p.waypoints[+b.dataset.waypoint].xy,180));panel.querySelectorAll('[data-remove-waypoint]').forEach(b=>b.onclick=()=>{p.waypoints.splice(+b.dataset.removeWaypoint,1);persist();calculate();render();});$('#journeySeaPace').oninput=$('#journeySeaPace').onchange=e=>{if(e.target.value==='custom'){panel.querySelector('[data-setting=shipSpeed]').focus();return;}p.settings=options({...p.settings,shipSpeed:+e.target.value});persist();calculate();render();};panel.querySelectorAll('[data-setting]').forEach(input=>{const update=()=>{p.settings=options({...p.settings,[input.dataset.setting]:input.type==='checkbox'?input.checked:input.value});persist();calculate();if(input.dataset.setting==='shipSpeed')$('#journeySeaPace').value=[6,11,20].includes(p.settings.shipSpeed)?String(p.settings.shipSpeed):'custom';if(input.tagName==='SELECT'||input.type==='checkbox')render();else $('#journeyResult').innerHTML=result();};if(input.type==='number'){input.oninput=update;input.onblur=()=>input.value=p.settings[input.dataset.setting];}else input.onchange=update;});
  $('#routeName').oninput=e=>routeDraft=e.target.value;$('#savePlan').onclick=()=>{if(!validRoute())return;if(p.plans.length>=50)return toast('Limite de 50 planos por grupo.');p.plans.push({name:$('#routeName').value.trim()||`Plano ${p.plans.length+1}`,waypoints:structuredClone(p.waypoints),settings:{...p.settings}});persist();render();toast('Plano salvo sem mover o grupo');};$('#recordJourney').onclick=()=>{if(!validRoute())return;if(lastSimulation.blocked)return toast('Corrija o excesso de carga antes de registrar.');if(p.history.length>=100)return toast('Limite de 100 trechos por grupo; exporte o histórico antes de iniciar outro grupo.');const s=lastSimulation;p.history.push({name:$('#routeName').value.trim()||`Trecho ${p.history.length+1}`,date:new Date().toISOString(),points:structuredClone(lastRoute.points),distance:s.distance,moving:s.moving,elapsed:s.elapsed,from:p.waypoints[0].label,to:p.waypoints.at(-1).label});routeDraft='';p.location=structuredClone(p.waypoints.at(-1));p.waypoints=[structuredClone(p.location)];picking=null;persist();calculate();render();toast('Trecho registrado; posição atualizada');};
  panel.querySelectorAll('[data-plan]').forEach(b=>b.onclick=()=>{const r=p.plans[+b.dataset.plan];if(p.location&&Math.hypot(...r.waypoints[0].xy.map((v,i)=>v-p.location.xy[i]))>.1)return toast('Este plano começa em outra posição. Reposicione o grupo antes de usá-lo.');p.waypoints=structuredClone(r.waypoints);p.settings={...r.settings};persist();calculate();render();});panel.querySelectorAll('[data-delete-plan]').forEach(b=>b.onclick=()=>{p.plans.splice(+b.dataset.deletePlan,1);persist();render();});panel.querySelectorAll('[data-history]').forEach(b=>b.onclick=()=>{const h=p.history[+b.dataset.history];focus(...h.points[Math.floor(h.points.length/2)],450);});$('#journeyBody').scrollTop=scrollTop;
 }
 function planRoute(r){browseRouteId=r.id;const p=active();if(!p){toast('Crie um grupo para planejar esta rota.');panel.hidden=false;render();return;}let controls=(r.controls||[r.points[0],r.points.at(-1)]).map(x=>({xy:x.slice(0,2),label:r.name}));if(p.location&&Math.hypot(...controls.at(-1).xy.map((v,i)=>v-p.location.xy[i]))<Math.hypot(...controls[0].xy.map((v,i)=>v-p.location.xy[i])))controls.reverse();if(!p.location){p.location=structuredClone(controls[0]);p.waypoints=[structuredClone(p.location)];controls=controls.slice(1);}if(p.waypoints.length+controls.length>200)return toast('Este traçado precisa ser dividido em trechos menores.');p.waypoints.push(...controls);picking=null;collapsed=false;panel.hidden=false;persist();calculate();render();}
 function validRoute(){if(routeError||!lastSimulation?.distance||!lastRoute?.points.length){toast(routeError||'Adicione um destino para traçar a rota.');return false;}return true;}
 function startPick(mode){if(!active())return toast('Crie um grupo primeiro.');picking=mode;collapsed=true;render();}
 async function pick(xy,label=''){const p=active();if(!p)return false;if(router.nearest(xy).h<20&&!router.isSeaPoint(xy)){toast('Escolha terra, um porto ou uma rota marítima cadastrada.');return true;}const wp={xy:[...xy],label:label||`Ponto ${fmt(xy[0])}, ${fmt(xy[1])}`};if(picking==='location'){if(p.history.length&&!await confirmJourney('Reposicionar o grupo sem registrar deslocamento? O histórico existente será mantido.'))return true;p.location=wp;p.waypoints=[structuredClone(wp)];picking=null;collapsed=false;}else{if(!p.location){p.location=wp;p.waypoints=[structuredClone(wp)];}else{if(p.waypoints.length>=200)return toast('Limite de 200 paradas por plano.');if(!p.waypoints.length)p.waypoints=[structuredClone(p.location)];p.waypoints.push(wp);}}persist();calculate();render();return true;}
 calculate();render();return {refresh(){calculate();render();},forgetCity(city){
 const matches=p=>p&&[ [city.x,city.y],city.harbor?.waterPoint].filter(Boolean).some(xy=>Math.hypot(p.xy[0]-xy[0],p.xy[1]-xy[1])<.2);
 for(const p of data.parties){if(matches(p.location))p.location.label='Localização no mapa';for(const wp of p.waypoints)if(matches(wp))wp.label='Ponto de passagem';for(const plan of p.plans)for(const wp of plan.waypoints)if(matches(wp))wp.label='Ponto de passagem';}persist();calculate();render();
 },open(){panel.hidden=false;document.querySelector('#detail').hidden=true;const layers=document.querySelector('#layerOptions');layers.hidden=true;layers.style.display='none';calculate();render();},isPicking:()=>!!picking&&!panel.hidden,pick,exportData:()=>structuredClone(data),importData(raw){const cleaned=cleanJourneys(raw);data=upgradeSeaPace(cleaned);picking=null;persist();calculate();render();},planRoute,cancel(){picking=null;collapsed=false;render();}};
}
